from __future__ import unicode_literals

from copy import deepcopy
from ..scfc.exceptions import NoSuchListParameter, NoSuchParameter

from ute_common_config_files.raml.xml import Xml
from ute_common_config_files.raml.param import Param
from ..scfc.list_param import ListParam


class ManagedObject(Xml):

    LIST_PATH = '{*}list[@name="{list_name}"]'
    LIST_ITEMS_PATH = LIST_PATH + '/{*}item'
    ALL_LISTS_PATH = '{*}list'
    PARAM_PATH = '{*}p[@name="{param_name}"]'
    ALL_PARAM_PATH = '{*}p'
    LIST_WRAPPER_PATH = '{*}list[@name="{param_name}"]'
    PARAM_MULTIPLE_PATH = LIST_WRAPPER_PATH + '/{*}p'

    @property
    def version(self):
        """Version (eNB SW branch) of this managed object"""
        return self.xml.get('version')

    @property
    def dist_name(self):
        """Dist name of this managed object"""
        return self.xml.get('distName')

    @dist_name.setter
    def dist_name(self, value):
        """Dist name of this managed object"""
        self.xml.set('distName', value)

    @property
    def id(self):
        """Id of this managed object (last part of dist name, e.g. 2 for DIST-1/NAME-2)"""
        return int(self.dist_name.rsplit('-', 1)[1])

    @id.setter
    def id(self, value):
        """Id of this managed object (last part of dist name, e.g. 2 for DIST-1/NAME-2)"""
        splited_dist_name = self.dist_name.split("-")
        splited_dist_name[-1] = str(value)
        self.dist_name = "-".join(splited_dist_name)

    @property
    def klass(self):
        """Class of this managed object"""
        return self.xml.get('class')

    @property
    def prefix(self):
        """Return prefix of class"""
        splited_class = self.klass.split(':')
        return splited_class[1] if len(splited_class) == 2 else None

    def remove(self):
        """Removes this managed object from SCFC"""
        self._remove_element(self.xml)

    def find_all_list_params(self):
        """Returns a list of objects representing all list parameters"""
        managed_object_nodes = self._find_all_nodes(self.ALL_LISTS_PATH)
        return [ListParam(node) for node in managed_object_nodes]

    def find_list_param(self, list_name):
        """Returns a list of objects representing all lists with given name"""
        list_node = self._find_node_or_raise(self.LIST_PATH, list_name=list_name, exception_class=NoSuchListParameter)
        return ListParam(list_node)

    def has_list_param(self, list_name):
        """Returns true if this managed object contains a list parameter named param_name, false otherwise"""
        results = self._find_node(self.LIST_PATH, list_name=list_name, exception_class=NoSuchListParameter)
        return True if results is not None else False

    def find_param(self, param_name, param_value=None):
        """Returns an object representing the first matching parameter with given name and value in this managed object.
        Parameters inside lists are skipped."""
        node = self._find_param_node(param_name, param_value)
        return Param(node)

    def find_all_params(self):
        """Returns a list of objects representing all parameters"""
        return [Param(node) for node in self._find_all_nodes(self.ALL_PARAM_PATH)]

    def has_param(self, param_name):
        """Returns true if this managed object contains a (non-list) parameter named param_name, false otherwise"""
        return self._find_node(self.PARAM_PATH, param_name=param_name) is not None \
            or self._find_node(self.PARAM_MULTIPLE_PATH, param_name=param_name) is not None

    def _find_param_node(self, param_name, param_value):
        if param_value is None:
            return self._find_param_node_by_name(param_name)
        else:
            return self._find_param_node_by_name_and_value(param_name, param_value)

    def find_params(self, param_name):
        """Returns a list of objects representing all parameters with given name"""
        return [Param(node) for node in self._find_all_param_nodes_by_name(param_name)]

    def _find_param_node_by_name(self, param_name):
        param_node = self._find_node(self.PARAM_PATH, param_name=param_name)
        if param_node is None:
            param_node = self._find_node(self.PARAM_MULTIPLE_PATH, param_name=param_name)
        if param_node is None:
            self._raise_on_node_not_found(NoSuchParameter, self.xml, self.PARAM_PATH + ' or ' + self.PARAM_MULTIPLE_PATH, param_name=param_name)
        return param_node

    def _find_all_param_nodes_by_name(self, param_name):
        return self._find_all_nodes(self.PARAM_PATH, param_name=param_name) \
            + self._find_all_nodes(self.PARAM_MULTIPLE_PATH, param_name=param_name)

    def _find_param_node_by_name_and_value(self, param_name, param_value):
        param_nodes = self._find_all_param_nodes_by_name(param_name)
        nodes_with_value = [node for node in param_nodes if node.text == param_value]
        if len(nodes_with_value) == 0:
            self._raise_on_node_not_found(NoSuchParameter, self.xml, self.PARAM_PATH + ' or ' + self.PARAM_MULTIPLE_PATH,
                                          param_name=param_name, param_value=param_value)
        else:
            return nodes_with_value[0]

    def add_param(self, param_name, param_value, multiple=False):
        """Adds a parameter to this managed object"""
        if multiple:
            return self._add_duplictated_param(param_name, param_value)
        else:
            return self._add_single_param(param_name, param_value)

    def add_param_or_set_value_in_existing(self, param_name, param_value, multiple=False):
        """If a parameter named param_name exists, its value is set to param_value.
        Otherwise a new parameter is created with given name and value."""
        if self.has_param(param_name):
            param = self.find_param(param_name)
            param.value = param_value
            return param
        else:
            return self.add_param(param_name, param_value, multiple)

    def add_list_param(self, list_name):
        """Adds an empty list to this managed object"""
        list_node = self._add_element(self.xml, 'list')
        list_node.set('name', list_name)
        return ListParam(list_node)

    def _add_single_param(self, param_name, param_value):
        param_node = self._add_element(self.xml, 'p')
        param_node.set('name', param_name)
        param_node.text = str(param_value)
        return Param(param_node)

    def _add_duplictated_param(self, param_name, param_value):
        self._ensure_list_wrapper_for_duplicated_param_exists(param_name)
        list_wrapper_node = self._find_list_wrapper_for_duplicated_param(param_name)
        param_element = self._add_element(list_wrapper_node, 'p')
        param_element.text = str(param_value)
        return Param(param_element)

    def _ensure_list_wrapper_for_duplicated_param_exists(self, param_name):
        if self._find_list_wrapper_for_duplicated_param(param_name) is None:
            self._add_list_wrapper_for_duplicated_param(param_name)

    def _find_list_wrapper_for_duplicated_param(self, param_name):
        return self._find_node(self.LIST_WRAPPER_PATH, param_name=param_name)

    def _add_list_wrapper_for_duplicated_param(self, param_name):
        list_element = self._add_element(self.xml, 'list')
        list_element.set('name', param_name)
        self._fix_inner_indentation(list_element)

    def remove_param(self, param_name, param_value=None):
        """Removes the first found parameter with given name and value (not inside a list)"""
        node_to_remove = self._find_param_node(param_name, param_value)
        self._remove_element(node_to_remove)

    def remove_params(self, param_name):
        """Removes all parameters with given name (not inside a list)"""
        nodes_to_remove = self._find_all_param_nodes_by_name(param_name)
        for node_to_remove in nodes_to_remove:
            self._remove_element(node_to_remove)

    def clone(self, new_id, **kwargs):
        """Clones object (self) and sets new id, and sets params values using kwargs"""
        cloned_mo = deepcopy(self)
        cloned_mo.id = new_id
        for name, value in kwargs.items():
            cloned_mo.find_param(name).value = value
        parent = self.xml.getparent()
        parent.append(cloned_mo.xml)
        return cloned_mo
